551	// semantic merge: log.md (union of entries) or index.md (3-way merge per
552	// listing). It returns ok=false for any other file, or when the merge cannot
553	// be done safely, so the caller falls back to the collision failsafe.
554	func (e *Engine) mergeBookkeeping(ctx context.Context, c Conflict, localPlain []byte) ([]byte, bool) {
555		switch {
556		case isLogFile(c.Path):
557			remotePlain, err := e.fetchPlaintext(ctx, c.RemoteEntry.BlobHash)
558			if err != nil {
559				return nil, false
560			}
561			merged, err := MergeLogContent(localPlain, remotePlain)
562			return merged, err == nil
563	
564		case isIndexFile(c.Path):
565			remotePlain, err := e.fetchPlaintext(ctx, c.RemoteEntry.BlobHash)
566			if err != nil {
567				return nil, false
568			}
569			var basePlain []byte
570			if c.BaseEntry != nil && c.BaseEntry.BlobHash != "" {
571				if basePlain, err = e.fetchPlaintext(ctx, c.BaseEntry.BlobHash); err != nil {
572					return nil, false
573				}
574			}
